#!/usr/bin/env python3

from __future__ import annotations

import math
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable
from xml.sax.saxutils import escape


VERSION_TEXT = "Cppcheck 2.19 dev\n"
SOURCE_EXTENSIONS = (".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx")
VALID_ENABLES = {
    "warning",
    "performance",
    "portability",
    "information",
    "style",
    "unusedFunction",
    "missingInclude",
    "all",
}
CHECKERS_REPORT_MESSAGE = (
    "Active checkers: 113/186 (use --checkers-report=<filename> to see details)"
)
HELP_TEXT = (Path(__file__).resolve().parent / "help.txt").read_text(encoding="utf-8")

DECLARATION_RE = re.compile(
    r"\b(?:auto|char|const|double|float|int|long|short|signed|static|unsigned|void|volatile)\b"
    r"(?:\s+\b(?:char|const|double|float|int|long|short|signed|static|unsigned|void|volatile)\b)*"
    r"\s+([A-Za-z_]\w*)\s*\[\s*(\d+)\s*\]"
)
ACCESS_RE = re.compile(r"\b([A-Za-z_]\w*)\s*\[\s*(\d+)\s*\]")
ASSIGN_RE = re.compile(r"(?<![=!<>+\-*/%&|^])\b([A-Za-z_]\w*(?:\s*\[\s*\d+\s*\])?)\s*=(?![=])")
SCALAR_DECL_ASSIGN_RE = re.compile(
    r"\b(?:auto|char|const|double|float|int|long|short|signed|static|unsigned|void|volatile)\b"
    r"(?:\s+\b(?:char|const|double|float|int|long|short|signed|static|unsigned|void|volatile)\b)*"
    r"\s+([A-Za-z_]\w*)\s*="
)
STATIC_FUNCTION_RE = re.compile(r"^\s*static\b[^\n;]*?\b([A-Za-z_]\w*)\s*\([^;{}]*\)\s*(\{)?")
