@dataclass
class Config:
    quiet: bool = False
    output_format: str = "text"
    template: str | None = None
    error_exitcode: int | None = None
    enable_style: bool = False
    enable_unused_function: bool = False
    enable_all: bool = False
    inline_suppr: bool = False
    jobs: int = 1
    output_file: str | None = None


@dataclass
class InputFile:
    display_path: str
    actual_path: str
    size: int


@dataclass
class Diagnostic:
    file: str
    line: int
    column: int
    severity: str
    message: str
    diag_id: str
    cwe: str | None = None
    code_line: str | None = None
    info: str | None = None
    symbol: str | None = None
    file0: str | None = None


def print_help() -> int:
    sys.stdout.write(HELP_TEXT)
    return 0


def print_version() -> int:
    sys.stdout.write(VERSION_TEXT)
    return 0


def fail(message: str) -> int:
    sys.stdout.write(f"cppcheck: error: {message}\n")
    return 1


def iter_early_actions(argv: list[str]) -> int | None:
    if not argv:
        return print_help()
    for arg in argv:
        if arg in ("-h", "--help"):
            return print_help()
        if arg == "--version":
            return print_version()
    return None


def parse_args(argv: list[str]) -> tuple[Config, list[str]] | int:
    early = iter_early_actions(argv)
    if early is not None:
        return early

    cfg = Config()
    paths: list[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            paths.extend(argv[i + 1 :])
            break
        if not arg.startswith("-") or arg == "-":
            paths.append(arg)
            i += 1
            continue
        if arg in ("-q", "--quiet"):
            cfg.quiet = True
            i += 1
            continue
        if arg == "--xml":
            cfg.output_format = "xml"
            i += 1
            continue
        if arg.startswith("--output-format="):
            value = arg.split("=", 1)[1]
            if value in ("xml", "xmlv2", "xmlv3"):
                cfg.output_format = "xml"
            else:
                cfg.output_format = "text"
            i += 1
            continue
        if arg.startswith("--template="):
            value = arg.split("=", 1)[1]
            cfg.template = value or None
            i += 1
            continue
        if arg.startswith("--output-file="):
            cfg.output_file = arg.split("=", 1)[1]
            i += 1
            continue
        if arg.startswith("--error-exitcode="):
            value = arg.split("=", 1)[1]
            if not value or not re.fullmatch(r"[+-]?\d+", value):
                return fail("argument to '--error-exitcode=' is not valid - not an integer.")
            cfg.error_exitcode = int(value, 10)
            i += 1
            continue
        if arg == "--error-exitcode":
            return fail('unrecognized command line option: "--error-exitcode".')
        if arg.startswith("--enable="):
            enable_values = [part for part in arg.split("=", 1)[1].split(",") if part]
            for value in enable_values:
                if value not in VALID_ENABLES:
                    return fail(f"--enable parameter with the unknown name '{value}'")
                if value == "style":
                    cfg.enable_style = True
                elif value == "unusedFunction":
                    cfg.enable_unused_function = True
                elif value == "all":
                    cfg.enable_style = True
                    cfg.enable_unused_function = True
                    cfg.enable_all = True
            i += 1
            continue
        if arg == "--inline-suppr":
            cfg.inline_suppr = True
            i += 1
            continue
        if arg == "-j":
            if i + 1 >= len(argv) or argv[i + 1].startswith("-"):
                return fail("argument to '-j' is missing.")
            value = argv[i + 1]
            if not re.fullmatch(r"\d+", value):
                return fail("argument to '-j' is not valid - not an integer.")
            if int(value, 10) <= 0:
                return fail("argument for '-j' must be greater than 0.")
            cfg.jobs = int(value, 10)
            i += 2
            continue
        if arg.startswith("-j") and arg != "-j":
            value = arg[2:]
            if not re.fullmatch(r"\d+", value):
                return fail("argument to '-j' is not valid - not an integer.")
            if int(value, 10) <= 0:
                return fail("argument for '-j' must be greater than 0.")
            cfg.jobs = int(value, 10)
            i += 1
            continue
        consumed = consume_ignored_option(argv, i)
        if consumed is not None:
            i = consumed
            continue
        return fail(f'unrecognized command line option: "{arg}".')

    if not paths:
        return fail("no C or C++ source files found.")
    return cfg, paths


def consume_ignored_option(argv: list[str], index: int) -> int | None:
    arg = argv[index]
    if arg in ("-f", "--force", "--fsigned-char", "--funsigned-char", "--inconclusive", "-v", "--verbose", "--dump", "--check-config", "--check-library", "--report-progress", "--safety", "--errorlist", "-E"):
        return index + 1
    if arg.startswith(("-D", "-U")) and len(arg) > 2:
        return index + 1
    if arg.startswith(
        (
            "--addon=",
            "--addon-python=",
            "--cppcheck-build-dir=",
            "--check-level=",
            "--checkers-report=",
            "--clang=",
            "--config-exclude=",
            "--config-excludes-file=",
            "--disable=",
            "--exitcode-suppressions=",
            "--file-filter=",
            "--file-list=",
            "--includes-file=",
            "--include=",
            "--language=",
            "--library=",
            "--max-configs=",
            "--max-ctu-depth=",
            "--platform=",
            "--plist-output=",
            "--project=",
            "--project-configuration=",
            "-rp=",
            "--relative-paths=",
            "--report-type=",
            "--rule=",
            "--rule-file=",
            "--showtime=",
            "--std=",
            "--suppress=",
            "--suppressions-list=",
            "--suppress-xml=",
            "--template-location=",
        )
    ):
        return index + 1
    if arg in ("-I", "-i", "-l", "-x"):
        if index + 1 >= len(argv):
            return len(argv)
        return index + 2
    if arg.startswith(("-I", "-i", "-l", "-x")) and len(arg) > 2:
        return index + 1
    if arg == "--clang":
        return index + 1
    return None


def discover_files(paths: Iterable[str]) -> list[InputFile]:
    files: list[InputFile] = []
    for raw_path in paths:
        if not raw_path:
            continue
        if os.path.isfile(raw_path):
            files.append(InputFile(raw_path, raw_path, file_size(raw_path)))
            continue
        if os.path.isdir(raw_path):
            root = Path(raw_path)
            discovered: list[str] = []
            for path in root.rglob("*"):
                if path.is_file() and path.name.lower().endswith(SOURCE_EXTENSIONS):
                    relative = path.relative_to(root)
                    display = join_display_path(raw_path, str(relative).replace(os.sep, "/"))
                    discovered.append(display)
            for display in sorted(discovered):
                actual = os.path.join(raw_path, display[len(raw_path) + 1 :]) if raw_path else display
                files.append(InputFile(display, actual, file_size(actual)))
    return files


def join_display_path(base: str, relative: str) -> str:
    if base.endswith("/"):
        return f"{base}{relative}"
    return f"{base}/{relative}"


def file_size(path: str) -> int:
    try:
        return os.path.getsize(path)
    except OSError:
        return 0


def analyze_file(input_file: InputFile, cfg: Config) -> list[Diagnostic]:
    try:
        text = Path(input_file.actual_path).read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return []
    lines = text.splitlines()
    declarations = collect_array_declarations(lines)

    errors: list[Diagnostic] = []
    styles: list[Diagnostic] = []
    unused_functions: list[Diagnostic] = []

    for line_number, line in enumerate(lines, start=1):
        declaration_spans = [match.span() for match in DECLARATION_RE.finditer(line)]
        for match in ACCESS_RE.finditer(line):
            if any(span[0] <= match.start() < span[1] for span in declaration_spans):
                continue
            name = match.group(1)
            index = int(match.group(2), 10)
            if name not in declarations:
                continue
            declared_size = declarations[name]
            if index < declared_size:
                continue
            diag = Diagnostic(
                file=input_file.display_path,
                line=line_number,
                column=match.start() + 1,
                severity="error",
                message=f"Array '{name}[{declared_size}]' accessed at index {index}, which is out of bounds.",
                diag_id="arrayIndexOutOfBounds",
                cwe="788",
                code_line=line,
                info="Array index out of bounds",
                file0=input_file.display_path,
            )
            if not is_suppressed(lines, line_number, diag.diag_id, cfg.inline_suppr):
                errors.append(diag)

    if cfg.enable_style:
        styles.extend(find_unread_variables(input_file.display_path, lines, cfg.inline_suppr))
    if cfg.enable_unused_function:
        unused_functions.extend(find_unused_functions(input_file.display_path, lines, cfg.inline_suppr))
    return errors + styles + unused_functions


def collect_array_declarations(lines: list[str]) -> dict[str, int]:
    declarations: dict[str, int] = {}
    for line in lines:
        for match in DECLARATION_RE.finditer(line):
            declarations[match.group(1)] = int(match.group(2), 10)
    return declarations


def find_unread_variables(display_path: str, lines: list[str], inline_suppr: bool) -> list[Diagnostic]:
    text = "\n".join(lines)
    diagnostics: list[Diagnostic] = []
    for line_number, line in enumerate(lines, start=1):
        for match in ASSIGN_RE.finditer(line):
            target = normalize_target(match.group(1))
            if "(" in target:
                continue
            is_scalar_decl = bool(SCALAR_DECL_ASSIGN_RE.search(line[: match.end()]))
            if "[" not in target and not is_scalar_decl:
                continue
            if target in {"return", "if", "while", "for", "switch"}:
                continue
            variable_name = target.split("[", 1)[0]
            remainder_same_line = line[match.end() :]
            remainder_text = remainder_same_line + "\n" + "\n".join(lines[line_number:])
            if re.search(rf"\b{re.escape(variable_name)}\b", remainder_text):
                continue
            message_target = target
            diag = Diagnostic(
                file=display_path,
                line=line_number,
                column=line.find("=", match.start()) + 1,
                severity="style",
                message=f"Variable '{message_target}' is assigned a value that is never used.",
                diag_id="unreadVariable",
                cwe="563",
                code_line=line,
                symbol=message_target,
                file0=display_path,
            )
            if not is_suppressed(lines, line_number, diag.diag_id, inline_suppr):
                diagnostics.append(diag)
    return diagnostics


def normalize_target(target: str) -> str:
    return re.sub(r"\s+", "", target)


def find_unused_functions(display_path: str, lines: list[str], inline_suppr: bool) -> list[Diagnostic]:
    text = "\n".join(lines)
    diagnostics: list[Diagnostic] = []
    for line_number, line in enumerate(lines, start=1):
        match = STATIC_FUNCTION_RE.match(line)
        if not match:
            continue
        name = match.group(1)
        occurrences = list(re.finditer(rf"\b{re.escape(name)}\b", text))
        if len(occurrences) > 1:
            continue
        diag = Diagnostic(
            file=display_path,
            line=line_number,
            column=match.start(1) + 1,
            severity="style",
            message=f"The function '{name}' is never used.",
            diag_id="unusedFunction",
            cwe="561",
            code_line=line,
            symbol=name,
        )
        if not is_suppressed(lines, line_number, diag.diag_id, inline_suppr):
            diagnostics.append(diag)
    return diagnostics


def is_suppressed(lines: list[str], line_number: int, diag_id: str, enabled: bool) -> bool:
    if not enabled:
        return False
    index = line_number - 2
    while index >= 0:
        stripped = lines[index].strip()
        if not stripped:
            index -= 1
            continue
        if not stripped.startswith("//"):
            break
        match = SUPPRESS_RE.search(stripped)
        if match and match.group(1) in (diag_id, "*"):
            return True
        index -= 1
    return False


def render_text(diag: Diagnostic, template: str | None) -> str:
    if template == "cppcheck1":
        return f"[{diag.file}:{diag.line}]: ({diag.severity}) {diag.message}\n"
    if template == "vs":
        return f"{diag.file}({diag.line}): {diag.severity}: {diag.message}\n"
    if template == "edit":
        return f"{diag.file} +{diag.line}: {diag.severity}: {diag.message}\n"
    if template == "gcc":
        first = f"{diag.file}:{diag.line}:{diag.column}: warning: {diag.message} [{diag.diag_id}]\n"
        if diag.code_line is None:
            return first + "\n"
        return first + f"{diag.code_line}\n" + (" " * (diag.column - 1)) + "^\n"
    if template:
        return apply_template(template, diag) + "\n"
    first = f"{diag.file}:{diag.line}:{diag.column}: {diag.severity}: {diag.message} [{diag.diag_id}]\n"
    if diag.code_line is None:
        return first + "\n"
    return first + f"{diag.code_line}\n" + (" " * (diag.column - 1)) + "^\n"


def apply_template(template: str, diag: Diagnostic) -> str:
    values = {
        "file": diag.file,
        "line": str(diag.line),
        "column": str(diag.column),
        "callstack": f"[{diag.file}:{diag.line}]",
        "severity": diag.severity,
        "message": diag.message,
        "id": diag.diag_id,
        "cwe": diag.cwe or "",
        "code": diag.code_line or "",
    }

    def inconclusive_repl(match: re.Match[str]) -> str:
        return ""

    rendered = INCONCLUSIVE_RE.sub(inconclusive_repl, template)
    rendered = PLACEHOLDER_RE.sub(lambda m: values[m.group(1)], rendered)
    rendered = rendered.replace("\\t", "\t").replace("\\n", "\n").replace("\\r", "\r")
    return rendered


def render_xml(diags: list[Diagnostic]) -> str:
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<results version="2">',
        '    <cppcheck version="2.19 dev"/>',
        '    <errors>',
    ]
    for diag in diags:
        msg = escape(diag.message, {"'": "&apos;"})
        if diag.diag_id == "checkersReport":
            lines.append(
                f'        <error id="{diag.diag_id}" severity="{diag.severity}" msg="{msg}" verbose="{msg}"/>'
            )
            continue
        attrs = [
            f'id="{diag.diag_id}"',
            f'severity="{diag.severity}"',
            f'msg="{msg}"',
            f'verbose="{msg}"',
        ]
        if diag.cwe:
            attrs.append(f'cwe="{diag.cwe}"')
        if diag.file0:
            attrs.append(f'file0="{escape(diag.file0, {"\'": "&apos;"})}"')
        lines.append(f"        <error {' '.join(attrs)}>")
        location_attrs = [
            f'file="{escape(diag.file, {"\'": "&apos;"})}"',
            f'line="{diag.line}"',
            f'column="{diag.column}"',
        ]
        if diag.info:
            location_attrs.append(f'info="{escape(diag.info, {"\'": "&apos;"})}"')
        lines.append(f"            <location {' '.join(location_attrs)}/>")
        if diag.symbol is not None:
            lines.append(f"            <symbol>{escape(diag.symbol, {'\'': '&apos;'})}</symbol>")
        lines.append("        </error>")
    lines.extend(["    </errors>", "</results>"])
    return "\n".join(lines) + "\n"


def run(cfg: Config, files: list[InputFile]) -> int:
    total_size = sum(max(file.size, 0) for file in files)
    processed_size = 0
    all_diags: list[Diagnostic] = []
    out_stream = sys.stderr
    file_handle = None
    if cfg.output_file:
        file_handle = open(cfg.output_file, "w", encoding="utf-8")
        out_stream = file_handle

    try:
        for index, input_file in enumerate(files, start=1):
            if not cfg.quiet:
                sys.stdout.write(f"Checking {input_file.display_path} ...\n")
            all_diags.extend(analyze_file(input_file, cfg))
            processed_size += max(input_file.size, 0)
            if not cfg.quiet and len(files) > 1:
                percent = 100 if total_size <= 0 else math.floor(processed_size * 100 / total_size)
                sys.stdout.write(f"{index}/{len(files)} files checked {percent}% done\n")

        if cfg.enable_all:
            all_diags.append(
                Diagnostic(
                    file="nofile",
                    line=0,
                    column=0,
                    severity="information",
                    message=CHECKERS_REPORT_MESSAGE,
                    diag_id="checkersReport",
                )
            )

        if cfg.output_format == "xml":
            out_stream.write(render_xml(all_diags))
        else:
            for diag in all_diags:
                out_stream.write(render_text(diag, cfg.template))
    finally:
        if file_handle is not None:
            file_handle.close()

    if cfg.error_exitcode is not None and any(diag.severity != "information" for diag in all_diags):
        return cfg.error_exitcode
    return 0


def main(argv: list[str]) -> int:
    parsed = parse_args(argv)
    if isinstance(parsed, int):
        return parsed
    cfg, paths = parsed
    files = discover_files(paths)
    if not files:
        return fail("could not find or open any of the paths given.")
    return run(cfg, files)


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

