def discover_files(paths: Iterable[str]) -> list[InputFile]:
    files: list[InputFile] = []
    for raw_path in paths:
        if not raw_path:
            continue
        if os.path.isfile(raw_path):
            files.append(InputFile(raw_path, raw_path, file_size(raw_path)))
            continue
        if os.path.isdir(raw_path):
            root = Path(raw_path)
            discovered: list[str] = []
            for path in root.rglob("*"):
                if path.is_file() and path.name.lower().endswith(SOURCE_EXTENSIONS):
                    relative = path.relative_to(root)
                    display = join_display_path(raw_path, str(relative).replace(os.sep, "/"))
                    discovered.append(display)
            for display in sorted(discovered):
                actual = os.path.join(raw_path, display[len(raw_path) + 1 :]) if raw_path else display
                files.append(InputFile(display, actual, file_size(actual)))
    return files


def join_display_path(base: str, relative: str) -> str:
    if base.endswith("/"):
