def find_unread_variables(display_path: str, lines: list[str], inline_suppr: bool) -> list[Diagnostic]:
    text = "\n".join(lines)
    diagnostics: list[Diagnostic] = []
    for line_number, line in enumerate(lines, start=1):
        for match in ASSIGN_RE.finditer(line):
            target = normalize_target(match.group(1))
            if "(" in target:
                continue
            is_scalar_decl = bool(SCALAR_DECL_ASSIGN_RE.search(line[: match.end()]))
            if "[" not in target and not is_scalar_decl:
                continue
            if target in {"return", "if", "while", "for", "switch"}:
                continue
            variable_name = target.split("[", 1)[0]
            remainder_same_line = line[match.end() :]
            remainder_text = remainder_same_line + "\n" + "\n".join(lines[line_number:])
            if re.search(rf"\b{re.escape(variable_name)}\b", remainder_text):
                continue
            message_target = target
            diag = Diagnostic(
                file=display_path,
                line=line_number,
                column=line.find("=", match.start()) + 1,
                severity="style",
                message=f"Variable '{message_target}' is assigned a value that is never used.",
                diag_id="unreadVariable",
                cwe="563",
                code_line=line,
                symbol=message_target,
                file0=display_path,
            )
            if not is_suppressed(lines, line_number, diag.diag_id, inline_suppr):
                diagnostics.append(diag)
    return diagnostics


def normalize_target(target: str) -> str:
    return re.sub(r"\s+", "", target)


def find_unused_functions(display_path: str, lines: list[str], inline_suppr: bool) -> list[Diagnostic]:
    text = "\n".join(lines)
    diagnostics: list[Diagnostic] = []
    for line_number, line in enumerate(lines, start=1):
        match = STATIC_FUNCTION_RE.match(line)
        if not match:
            continue
        name = match.group(1)
        occurrences = list(re.finditer(rf"\b{re.escape(name)}\b", text))
        if len(occurrences) > 1:
            continue
        diag = Diagnostic(
            file=display_path,
            line=line_number,
            column=match.start(1) + 1,
            severity="style",
            message=f"The function '{name}' is never used.",
            diag_id="unusedFunction",
            cwe="561",
            code_line=line,
            symbol=name,
        )
        if not is_suppressed(lines, line_number, diag.diag_id, inline_suppr):
            diagnostics.append(diag)
    return diagnostics


def is_suppressed(lines: list[str], line_number: int, diag_id: str, enabled: bool) -> bool:
    if not enabled:
        return False
    index = line_number - 2
    while index >= 0:
        stripped = lines[index].strip()
        if not stripped:
            index -= 1
            continue
        if not stripped.startswith("//"):
            break
        match = SUPPRESS_RE.search(stripped)
        if match and match.group(1) in (diag_id, "*"):
            return True
        index -= 1
    return False


def render_text(diag: Diagnostic, template: str | None) -> str:
    if template == "cppcheck1":
        return f"[{diag.file}:{diag.line}]: ({diag.severity}) {diag.message}\n"
    if template == "vs":
        return f"{diag.file}({diag.line}): {diag.severity}: {diag.message}\n"
    if template == "edit":
        return f"{diag.file} +{diag.line}: {diag.severity}: {diag.message}\n"
    if template == "gcc":
        first = f"{diag.file}:{diag.line}:{diag.column}: warning: {diag.message} [{diag.diag_id}]\n"
        if diag.code_line is None:
            return first + "\n"
        return first + f"{diag.code_line}\n" + (" " * (diag.column - 1)) + "^\n"
    if template:
        return apply_template(template, diag) + "\n"
    first = f"{diag.file}:{diag.line}:{diag.column}: {diag.severity}: {diag.message} [{diag.diag_id}]\n"
    if diag.code_line is None:
        return first + "\n"
    return first + f"{diag.code_line}\n" + (" " * (diag.column - 1)) + "^\n"


