        "file": diag.file,
        "line": str(diag.line),
        "column": str(diag.column),
        "callstack": f"[{diag.file}:{diag.line}]",
        "severity": diag.severity,
        "message": diag.message,
        "id": diag.diag_id,
        "cwe": diag.cwe or "",
        "code": diag.code_line or "",
