def run(cfg: Config, files: list[InputFile]) -> int:
    total_size = sum(max(file.size, 0) for file in files)
    processed_size = 0
    all_diags: list[Diagnostic] = []
    out_stream = sys.stderr
    file_handle = None
    if cfg.output_file:
        file_handle = open(cfg.output_file, "w", encoding="utf-8")
        out_stream = file_handle

    try:
        for index, input_file in enumerate(files, start=1):
            if not cfg.quiet:
                sys.stdout.write(f"Checking {input_file.display_path} ...\n")
            all_diags.extend(analyze_file(input_file, cfg))
            processed_size += max(input_file.size, 0)
            if not cfg.quiet and len(files) > 1:
                percent = 100 if total_size <= 0 else math.floor(processed_size * 100 / total_size)
                sys.stdout.write(f"{index}/{len(files)} files checked {percent}% done\n")

        if cfg.enable_all:
            all_diags.append(
                Diagnostic(
                    file="nofile",
                    line=0,
                    column=0,
                    severity="information",
                    message=CHECKERS_REPORT_MESSAGE,
                    diag_id="checkersReport",
                )
            )

        if cfg.output_format == "xml":
            out_stream.write(render_xml(all_diags))
        else:
            for diag in all_diags:
                out_stream.write(render_text(diag, cfg.template))
    finally:
        if file_handle is not None:
            file_handle.close()

    if cfg.error_exitcode is not None and any(diag.severity != "information" for diag in all_diags):
        return cfg.error_exitcode
    return 0


